    def pow_mod(base: int, exponent: int, modulus: int) -> int:
        result = 1
        base = base % modulus
        while exponent > 0:
            if exponent % 2 == 1:
                result = (result * base) % modulus
            exponent //= 2
            base = (base * base) % modulus
        return result

    def modinv(a: int, b: int) -> int:
        return pow(a, -1, b)

    # Use Chinese Remainder Theorem for efficient computation
    def chinese_remainder(n, a):
        sum = 0
        prod = reduce(lambda a, b: a*b, n)

        for n_i, a_i in zip(n, a):
            p = prod // n_i
            sum += a_i * modinv(p, n_i) * p
        return sum % prod

    # Compute all powers of a modulo L
    pow_moduli = [L for _ in range(n)]
    for k in range(n):
        pow_moduli[k] = pow_mod(a, 2**k, L)
        pow_moduli[k] = chinese_remainder(pow_moduli[k:]+[1], [L for _ in range(n-k)])

